const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const human=v=>String(v||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const badge=v=>`<span class="badge ${esc(v)}">${esc(human(v))}</span>`;
const formatDate=d=>d?new Date(d).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'—';
const short=id=>id?.slice(0,6).toUpperCase()||'—';
const apiBase=(window.PANDORA_CONFIG?.apiBase||'').replace(/\/$/,'');
const n8nMode=window.PANDORA_CONFIG?.apiMode==='n8n';
let token=sessionStorage.getItem('pandora-session'),me,projects=[],data,projectId='',view='dashboard',filter={q:'',priority:'',status:'',type:'',owner:'',iteration:'',sort:'newest'},challengeId='',mailEmail='',toastTimer,modalRecord,chatMessages=[];
const paths=['dashboard','backlog','tests','iterations','insights','pipelines','activity','settings'];
const icons=['◫','☷','✓','▤','↗','⇄','◷','⚙'];
const titles=['Overview','Issue backlog','Test management','Iterations','Flow & DORA','Repositories & CI','Activity','Project settings'];
const isEditor=()=>['owner','developer'].includes(data?.role);
const isContributor=()=>['owner','developer','tester'].includes(data?.role);
const ownerName=id=>data?.members.find(m=>m.userId===id)?.user?.name||'Unassigned';
const url=(path)=>apiBase+'/api'+path;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
async function api(path,options={}){
  const request=n8nMode?{method:'POST',headers:{'Content-Type':'text/plain'},body:JSON.stringify({path,method:options.method||'GET',body:options.body,token:token||undefined})}:{...options,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})},body:options.body?JSON.stringify(options.body):undefined};
  for(let attempt=0;;attempt++){
    const r=await fetch(n8nMode?apiBase:url(path),request);
    const envelope=await r.json().catch(()=>({error:'Service unavailable'}));
    const status=n8nMode?(envelope.status||r.status):r.status,result=n8nMode?(envelope.body||{error:'Service unavailable'}):envelope;
    // Only lease contention is safe to replay: this response is emitted before any write.
    if(n8nMode&&r.ok&&status===409&&/^Another request is saving\./.test(result.error||'')&&attempt<5){await new Promise(resolve=>setTimeout(resolve,250*(attempt+1)));continue;}
    if(!r.ok||status>=400){if(status===401&&token){token=null;sessionStorage.removeItem('pandora-session');renderLogin();}throw new Error(result.error||'Request failed');}return result;
  }
}

const base=()=>`/projects/${projectId}`;
async function loadProjects(){projects=await api('/projects');if(!projects.some(p=>p.id===projectId))projectId=projects[0]?.id||'';await refresh();}
async function refresh(){data=projectId?await api(base()):null;render();}
function renderLogin(){
  $('#app').innerHTML=`<header class="login-header"><a href="./" class="brand"><span class="brand-mark">p</span>Pandora</a><img class="era" src="./eraneos-logo.svg" alt="Eraneos"></header><main id="main" class="landing"><section><span class="eyebrow">Engineering confidence · Together</span><h1>Every issue.<br>A path to<br><em>better software.</em></h1><p class="intro">Bring reports, test evidence and delivery into one shared workspace. From the first screenshot to the verified fix.</p><div class="journey"><span>Report</span><b>→</b><span>Prioritize</span><b>→</b><span>Resolve</span><b>→</b><span>Verify</span></div></section><section class="login-card"><span class="eyebrow">Your quality workspace</span><h2>Welcome to Pandora</h2><p>Sign in with your Eraneos email. Your projects and their evidence stay accessible only to project members.</p>${window.PANDORA_CONFIG?.deploymentReady===false?'<div class="notice">Sign-in is being configured. Please return shortly.</div>':''}<form id="login-form"><label>Work email<input name="email" type="email" autocomplete="email" placeholder="firstname.lastname@eraneos.com" value="${esc(mailEmail)}" required ${challengeId?'readonly':''}></label>${challengeId?'<label>8-digit login code<input name="code" inputmode="numeric" pattern="[0-9]{8}" autocomplete="one-time-code" minlength="8" maxlength="8" required></label>':''}<button class="btn dark" type="submit" ${window.PANDORA_CONFIG?.deploymentReady===false?'disabled':''}>${challengeId?'Verify & enter workspace':'Send login code'} <span>→</span></button>${challengeId?'<button class="btn quiet" type="button" data-action="reset-login">Use another email / request a new code</button>':''}<div class="login-status" role="status" id="login-status"></div></form><div class="login-foot">Verified @eraneos.com accounts only.<br>One-time code · 10-minute validity · No password to remember</div></section></main>`;
}
function render(){
  if(!me)return renderLogin();
  const unread=data?.notifications.filter(n=>!n.read).length||0;
  $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a href="./" class="brand"><span class="brand-mark">p</span>Pandora</a><label for="project-picker">Workspace</label><select id="project-picker" aria-label="Project">${projects.length?projects.map(p=>`<option value="${p.id}" ${p.id===projectId?'selected':''}>${esc(p.name)}</option>`).join(''):'<option>No projects yet</option>'}</select><button class="new-project" data-action="new-project">＋ Create project</button><nav class="nav" aria-label="Workspace navigation">${paths.map((v,i)=>`<button data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}><span aria-hidden="true">${icons[i]}</span>${titles[i]}</button>`).join('')}</nav><div class="sidebar-bottom"><span class="eyebrow">From signal to solution</span><p>Traceable changes.<br>Evidence you can trust.</p><div class="user-block"><span class="avatar">${esc(me.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(me.name)}</strong><small>${esc(data?.role||'Eraneos member')}</small></div><button data-action="logout" aria-label="Sign out">↪</button></div></div></aside><div class="workspace"><header class="topbar"><div class="crumb">Projects <span aria-hidden="true"> / </span> <strong>${esc(data?.project.name||'Your workspace')}</strong></div><div class="actions"><button class="btn quiet small" data-action="notifications">Inbox ${unread?`(${unread})`:''}</button><button class="btn quiet small" data-action="logout">Sign out</button><img class="era" src="./eraneos-logo.svg" alt="Eraneos"></div></header><main id="main" class="content">${data?renderPage():`<div class="page-heading"><div><span class="eyebrow">Welcome, ${esc(me.name)}</span><h1>Make quality a team effort.</h1><p>Create your first project to bring issues, iterations and test evidence together.</p></div></div><section class="panel empty"><strong>A clear starting point.</strong><p>You’ll become the project owner and can invite your team.</p><button class="btn primary" data-action="new-project">＋ Create your first project</button></section>`}</main></div></div>`;
}
function heading(title,sub,action=''){return `<div class="page-heading"><div><span class="eyebrow">${esc(data.project.name)} · ${esc(data.role)}</span><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function empty(title,detail=''){return `<div class="empty"><strong>${title}</strong>${detail}</div>`;}
function renderPage(){
  if(view==='dashboard')return dashboard();
  if(view==='backlog')return backlog();
  if(view==='tests')return tests();
  if(view==='iterations')return iterations();
  if(view==='insights')return insights();
  if(view==='pipelines')return pipelines();
  if(view==='activity')return activity();
  return settings();
}
function newIssueButton(){return isContributor()?'<button class="btn primary" data-action="new" data-kind="issues">＋ Report issue</button>':'';}
function dashboard(){
  const m=data.metrics,iter=data.iterations.find(i=>i.startDate<=new Date().toISOString().slice(0,10)&&i.endDate>=new Date().toISOString().slice(0,10))||data.iterations[0];
  return heading('A clearer view of quality.','Prioritize what matters. Keep delivery moving. Verify every fix.',newIssueButton())+`<div class="stats"><article class="stat"><span class="stat-label">Open issues <span>↗</span></span><strong>${m.open}</strong><small>Across all iterations</small></article><article class="stat highlight"><span class="stat-label">Critical attention <span>!</span></span><strong>${m.critical}</strong><small>Open critical-priority issues</small></article><article class="stat"><span class="stat-label">In progress <span>◷</span></span><strong>${m.wip}</strong><small>Active implementation work</small></article><article class="stat"><span class="stat-label">Verified & closed <span>✓</span></span><strong>${m.closed}</strong><small>${m.total?Math.round(m.closed/m.total*100):0}% of reported issues</small></article></div><div class="grid-two"><section class="panel"><div class="panel-title"><div><h2>Where to focus</h2><p>Open issues · Priority × severity</p></div><span class="badge">Heatmap</span></div>${heatmap()}</section><section class="panel"><div class="panel-title"><div><h2>Iteration burndown</h2><p>${iter?esc(iter.name)+' · remaining estimate points':'Set an iteration to start tracking progress'}</p></div>${iter?badge('live'):''}</div>${burndown(iter)}</section></div><div class="grid-two"><section class="panel"><div class="panel-title"><div><h2>Next in focus</h2><p>Highest-priority open issues</p></div><button class="btn quiet small" data-view="backlog">View backlog ↗</button></div>${issueTable(data.issues.filter(i=>i.status!=='closed').sort((a,b)=>priorityRank(a.priority)-priorityRank(b.priority)).slice(0,5),true)}</section><section class="panel"><div class="panel-title"><div><h2>Delivery rhythm</h2><p>Your iterations at a glance</p></div><button class="btn quiet small" data-view="iterations">All iterations ↗</button></div>${data.iterations.length?data.iterations.slice(0,3).map(iterationCard).join(''):empty('Plan your first iteration','Add dates and a goal, then assign issues from the backlog.')}<div class="notice">Agent assistance connects reporting with delivery. <button class="btn quiet small" data-action="chat">Open assistant ↗</button></div></section></div>`;
}
const priorityRank=p=>['critical','high','medium','low'].indexOf(p);
function heatmap(){
  const priorities=['critical','high','medium','low'],severities=['cosmetic','minor','major','critical'];
  return `<div class="heatmap"><span class="label">Priority ↓</span>${severities.map(s=>`<span class="label col-label">${human(s)}</span>`).join('')}${priorities.map(p=>`<span class="label">${human(p)}</span>${severities.map(s=>{const n=data.issues.filter(i=>i.status!=='closed'&&i.priority===p&&i.severity===s).length;return `<button class="cell ${n?'heat'+Math.min(n,4):''}" data-action="heatmap" data-priority="${p}" aria-label="${human(p)} priority, ${s} severity: ${n} open issues">${n||'—'}</button>`;}).join('')}`).join('')}</div><div class="legend">Severity → <span>Fewer</span><i></i><i></i><i></i><i></i><span>More issues</span></div>`;
}
function burndown(iter){
  if(!iter)return empty('No iteration data yet','Burndown uses recorded history, not projected completion.');
  const start=Date.parse(iter.startDate),end=Date.parse(iter.endDate),days=Math.min(366,Math.round((end-start)/86400000)+1),today=Date.now();
  const history=data.events.filter(e=>e.action.startsWith('issues.'));
  const points=[];for(let d=0;d<days;d++){const cutoff=start+(d+1)*86400000-1;if(start+d*86400000>today)break;const snapshot=new Map();for(const e of history)if(Date.parse(e.at)<=Math.min(cutoff,today))snapshot.set(e.entityId,e.after);const total=[...snapshot.values()].filter(i=>i&&i.iterationId===iter.id&&!i.deletedAt&&i.status!=='closed').reduce((a,i)=>a+i.estimate,0);points.push(total);}
  if(!points.length)return empty('Iteration has not started','Actual progress will appear when the iteration begins.');
  const initial=points[0],max=Math.max(...points,1),x=d=>40+d/Math.max(days-1,1)*400,y=n=>150-n/max*125;
  return `<svg viewBox="0 0 470 185" class="chart" role="img" aria-label="Iteration burndown, remaining estimate points. Current remaining: ${points.at(-1)}.">${[0,.5,1].map(v=>`<line class="gridline" x1="40" x2="440" y1="${y(v*max)}" y2="${y(v*max)}"/><text x="10" y="${y(v*max)+4}">${Math.round(v*max)}</text>`).join('')}<path class="ideal" d="M40,${y(initial)} L440,150"/><polyline class="actual" points="${points.map((p,d)=>`${x(d)},${y(p)}`).join(' ')}"/>${points.map((p,d)=>`<circle cx="${x(d)}" cy="${y(p)}" r="3" fill="#ff6b35"/>`).join('')}<text x="40" y="175">${esc(formatDate(iter.startDate))}</text><text x="350" y="175">${esc(formatDate(iter.endDate))}</text></svg><div class="chart-foot"><span><i class="dot"></i>Actual remaining</span><span><i class="dot grey"></i>Ideal from day-one scope</span><span>${points.at(-1)} points remaining</span></div>`;
}
function issueTable(items,compact=false){return items.length?`<div class="table-wrap"><table><thead><tr><th>Issue</th><th>Priority</th><th>Status</th>${compact?'':'<th>Owner</th><th>Iteration</th><th>Reported</th><th>Test</th>'}</tr></thead><tbody>${items.map(i=>`<tr><td><span class="ref">PD-${short(i.id)} · ${esc(i.type)}</span><button class="issue-link" data-action="edit" data-kind="issues" data-id="${i.id}">${esc(i.title)}</button><small>${data.attachments.filter(a=>a.issueId===i.id).length} screenshots · ${data.cases.filter(c=>c.issueId===i.id).length} tests</small></td><td>${badge(i.priority)}</td><td>${badge(i.status)}</td>${compact?'':`<td>${esc(ownerName(i.ownerId))}</td><td>${esc(data.iterations.find(x=>x.id===i.iterationId)?.name||'Backlog')}</td><td>${formatDate(i.createdAt)}<br><small>${esc(ownerName(i.createdBy))}</small></td><td>${badge(i.testStatus)}</td>`}</tr>`).join('')}</tbody></table></div>`:empty('Nothing here yet','Report an issue or adjust the filters.');}
function selectFilter(name,placeholder,options){return `<select aria-label="${placeholder}" data-filter="${name}"><option value="">${placeholder}</option>${options.map(o=>{const [value,label]=Array.isArray(o)?o:[o,human(o)];return `<option value="${esc(value)}" ${filter[name]===value?'selected':''}>${esc(label)}</option>`;}).join('')}</select>`;}
function filteredIssues(){const q=filter.q.toLowerCase();let list=data.issues.filter(i=>(!q||[i.title,i.description,i.id,i.steps,ownerName(i.createdBy)].join(' ').toLowerCase().includes(q))&&(!filter.priority||i.priority===filter.priority)&&(!filter.status||i.status===filter.status)&&(!filter.type||i.type===filter.type)&&(!filter.owner||i.ownerId===filter.owner)&&(!filter.iteration||i.iterationId===filter.iteration));return list.sort((a,b)=>filter.sort==='priority'?priorityRank(a.priority)-priorityRank(b.priority):filter.sort==='oldest'?a.createdAt.localeCompare(b.createdAt):b.createdAt.localeCompare(a.createdAt));}
function backlog(){return heading('From report to resolution.','One backlog. Clear ownership. Evidence at every step.',newIssueButton())+`<div class="toolbar"><input id="search" aria-label="Search issues" placeholder="Search title, description, reporter or ID…" value="${esc(filter.q)}">${selectFilter('priority','All priorities',['critical','high','medium','low'])}${selectFilter('status','All statuses',['reported','triaged','planned','in_progress','ready_for_test','verified','closed','reopened'])}${selectFilter('type','All types',['bug','defect','issue'])}</div><div class="toolbar">${selectFilter('owner','All owners',data.members.map(m=>[m.userId,m.user.name]))}${selectFilter('iteration','All iterations',data.iterations.map(i=>[i.id,i.name]))}<select data-filter="sort" aria-label="Sort issues"><option value="newest" ${filter.sort==='newest'?'selected':''}>Newest first</option><option value="oldest" ${filter.sort==='oldest'?'selected':''}>Oldest first</option><option value="priority" ${filter.sort==='priority'?'selected':''}>Priority first</option></select><button class="btn quiet" data-action="clear-filters">Reset filters</button></div><section class="panel" id="issue-results">${issueTable(filteredIssues())}<div class="table-count">${filteredIssues().length} of ${data.issues.length} issues</div></section>`;}
function iterationCard(i){const issues=data.issues.filter(x=>x.iterationId===i.id),done=issues.filter(x=>x.status==='closed').length;return `<article class="iteration-card"><div class="row-split"><h3>${esc(i.name)}</h3><small>${done}/${issues.length} closed</small></div><div class="iteration-meta"><span>${formatDate(i.startDate)} — ${formatDate(i.endDate)}</span><span>${issues.length?Math.round(done/issues.length*100):0}%</span></div><progress class="progress" value="${done}" max="${issues.length||1}" aria-label="Closed issues"></progress><small>${esc(i.goal)}</small></article>`;}
function iterations(){return heading('Find your delivery rhythm.','Iterations follow your cadence. Review suggested issue assignments; edit whenever needed.',isEditor()?`<div class="actions">${data.role==='owner'?'<button class="btn primary" data-action="configure-cadence">Configure cadence</button>':''}<button class="btn" data-action="new" data-kind="iterations">＋ Manual iteration</button></div>`:'')+iterationSuggestions()+`<div class="cards">${data.iterations.length?data.iterations.map(i=>`<section class="panel">${iterationCard(i)}${burndown(i)}${isEditor()?`<div class="actions"><button class="btn small" data-action="edit" data-kind="iterations" data-id="${i.id}">Edit iteration</button></div>`:''}</section>`).join(''):empty('No iterations yet','Start with a clear goal and a realistic timebox.')}</div>`;}
let aggregateTests=null;
function tests(){if(aggregateTests)return aggregateTestView();return '<div class="actions test-scope"><button class="btn" data-action="all-tests">All my projects</button></div>'+heading('Make confidence repeatable.','Test drafts are generated from issue evidence. Review, edit and execute them here or inside the issue.',isContributor()?'<div class="actions"><button class="btn" data-action="new" data-kind="cases">＋ Test case</button><button class="btn primary" data-action="new" data-kind="runs">＋ Record test run</button></div>':'')+`<section class="panel"><div class="panel-title"><div><h2>Test library</h2><p>Each run preserves the version of the case that was executed.</p></div><span class="badge">${data.cases.length} cases</span></div>${data.cases.length?`<div class="table-wrap"><table><thead><tr><th>Test case</th><th>Kind</th><th>Version</th><th>Linked issue</th><th></th></tr></thead><tbody>${data.cases.map(c=>`<tr><td><button class="issue-link" data-action="edit" data-kind="cases" data-id="${c.id}">${esc(c.title)}</button><br><small>${esc(c.expected.slice(0,100))}</small></td><td>${badge(c.kind)} ${c.source==='ai'?badge(c.manualEdited?'reviewed':'draft'):''}</td><td>v${c.version}</td><td>${c.issueId?'PD-'+short(c.issueId):'—'}</td><td>${isContributor()?`<button class="btn small" data-action="run-case" data-id="${c.id}">Run test →</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Build your first test case','Describe the steps and the expected result.')}</section><br><section class="panel"><div class="panel-title"><div><h2>Execution history</h2><p>Manual evidence today; pipeline results in phase two.</p></div></div>${data.runs.length?`<div class="table-wrap"><table><thead><tr><th>Test / version</th><th>Result</th><th>Environment / build</th><th>Tester</th><th>Date</th><th></th></tr></thead><tbody>${[...data.runs].reverse().map(r=>`<tr><td>${esc(r.caseSnapshot?.title||'Archived case')}<br><small>v${r.caseSnapshot?.version||1} · ${r.issueId?'PD-'+short(r.issueId):'No linked issue'}</small></td><td>${badge(r.result)}</td><td>${esc(r.environment)}<br><small>${esc(r.build)}</small></td><td>${esc(ownerName(r.createdBy))}</td><td>${formatDate(r.createdAt)}</td><td><button class="btn small" data-action="edit" data-kind="runs" data-id="${r.id}">Details</button></td></tr>`).join('')}</tbody></table></div>`:empty('No test executions yet','Record a result with environment, build and actual outcome.')}</section>`;}
function insights(){const m=data.metrics;return heading('Measure the system, improve the flow.','Use delivery evidence to understand progress and bottlenecks.')+`<section class="panel"><div class="panel-title"><div><h2>Flow metrics</h2><p>Computed from project issue history</p></div></div><div class="metric-list"><article><strong>${m.wip}</strong><span>Work in progress</span></article><article><strong>${m.throughput30d}</strong><span>Issues closed · last 30 days</span></article><article><strong>${m.cycleDays===null?'—':m.cycleDays.toFixed(1)+' d'}</strong><span>Median cycle time · started to closed</span></article><article><strong>${m.leadDays==null?'—':m.leadDays.toFixed(1)+' d'}</strong><span>Median lead time · reported to closed</span></article><article><strong>${m.agingDays==null?'—':m.agingDays.toFixed(1)+' d'}</strong><span>Median age of open issues</span></article></div></section><br><section class="panel"><div class="panel-title"><div><h2>DORA delivery metrics</h2><p>Production delivery outcomes, measured per connected repository</p></div><span class="badge">Awaiting deployment events</span></div><div class="metric-list">${['Deployment frequency','Change lead time','Failed deployment recovery time','Change fail rate','Deployment rework rate'].map(t=>`<article><strong>—</strong><span>${t}</span></article>`).join('')}</div><div class="notice">${esc(m.doraReason)} No deployment metrics are inferred from issue counts.</div></section>`;}
function activity(){return heading('A shared record of change.','Who changed what, and when. Archived records remain in the audit history.')+`<section class="panel">${data.events.length?[...data.events].reverse().slice(0,100).map(e=>`<article class="activity"><strong>${esc(human(e.action.replace('.',' ')))}</strong> · ${esc(e.after?.title||e.after?.name||short(e.entityId))}<small>${esc(ownerName(e.userId))} · ${new Date(e.at).toLocaleString()}</small></article>`).join(''):empty('No activity yet')}</section>`;}
function settings(){return heading('Set your team up for success.','Project access, ownership and notification preferences.')+`<div class="settings-grid"><section class="panel"><h2>Project details</h2><p>${esc(data.project.description||'No description yet.')}</p><p><small>Repository: ${esc(data.project.repository||'Not connected')}</small></p><p><small>Merge policy: ${esc(human(data.project.mergePolicy))}</small></p>${data.role==='owner'?'<button class="btn" data-action="edit-project">Edit project</button>':''}<div class="notice">Agentic merge is off. Phase two will require passing checks, repository protection and an owner-controlled opt-in before enabling it.</div><label><input type="checkbox" disabled>Agentic merge — phase two</label><hr><h3>Your notifications</h3><label><input id="mute-notifications" type="checkbox" ${data.preferences.muted?'checked':''}>Mute new in-app notifications for this project</label><p><small>Owners and developers receive delivery updates. Testers receive ready-for-test updates. Reporters and assignees receive relevant updates. Email notifications require a delivery integration.</small></p></section><section class="panel"><div class="panel-title"><h2>Project members</h2><span class="badge">${data.members.length}</span></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Role</th><th></th></tr></thead><tbody>${data.members.map(m=>`<tr><td>${esc(m.user.name)}<br><small>${esc(m.user.email)}</small></td><td>${badge(m.role)}</td><td>${data.role==='owner'?`<button class="btn small" data-action="remove-member" data-id="${m.userId}" aria-label="Remove ${esc(m.user.name)}">Remove</button>`:''}</td></tr>`).join('')}</tbody></table></div>${data.role==='owner'?`<form id="member-form"><h3>Add or change a member</h3><label>Eraneos email<input name="email" type="email" required></label><label>Project role<select name="role">${['developer','tester','viewer','owner'].map(r=>`<option>${r}</option>`).join('')}</select></label><button class="btn primary">Save membership</button></form>`:''}</section></div><br><section class="panel"><h2>Role responsibilities</h2><div class="table-wrap"><table><thead><tr><th>Role</th><th>Rights</th></tr></thead><tbody><tr><td>Owner</td><td>Project settings, membership, archive, delivery planning, verification and all records.</td></tr><tr><td>Developer / editor</td><td>Issue planning, mitigation, implementation, iterations, test cases and results. Cannot approve their own closure through this role.</td></tr><tr><td>Tester / user</td><td>Report issues, refine own reports, add evidence, maintain cases and runs, verify or reopen fixes.</td></tr><tr><td>Viewer</td><td>Read project records, evidence and activity. Advisory chat and personal notification settings.</td></tr></tbody></table></div></section>`;}
function openDialog(title,body){$('#modal').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button data-action="close-modal" aria-label="Close dialog">×</button></div><div class="dialog-body">${body}</div>`;$('#modal').showModal();}
function options(items,value){return items.map(o=>{const [v,label]=Array.isArray(o)?o:[o,human(o)];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(label)}</option>`;}).join('');}
function field(name,label,value='',type='text',opts=null,wide=false,required=false){return `<label class="${wide?'wide':''}">${label}${opts?`<select aria-label="${esc(label)}" name="${name}" ${required?'required':''}>${options(opts,value)}</select>`:type==='textarea'?`<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" max="1000" step="1"':''}>`}</label>`;}
function entityForm(kind,item={},preset={}){
  item={...item,...preset};modalRecord={kind,item,pendingFiles:[]};let fields='';const v=n=>item[n]??'';
  const issueOpts=[['','None'],...data.issues.map(i=>[i.id,'PD-'+short(i.id)+' · '+i.title])],iterOpts=[['','Backlog'],...data.iterations.map(i=>[i.id,i.name])];
  if(kind==='issues')fields=field('title','Issue title',v('title'),'text',null,true,true)+field('description','Description',v('description'),'textarea',null,true)+field('type','Type',v('type')||'bug','', ['bug','defect','issue'])+field('priority','Priority',v('priority')||'medium','',['critical','high','medium','low'])+field('severity','Severity',v('severity')||'minor','',['critical','major','minor','cosmetic'])+field('status','Workflow status',v('status')||'reported','',['reported','triaged','planned','in_progress','ready_for_test','verified','closed','reopened'])+field('ownerId','Mitigation owner',v('ownerId'),'', [['','Unassigned'],...data.members.filter(m=>['owner','developer'].includes(m.role)).map(m=>[m.userId,m.user.name])])+field('iterationId','Iteration',v('iterationId'),'',iterOpts)+field('dueDate','Due date',v('dueDate'),'date')+field('estimate','Estimate points',item.estimate??1,'number')+'<div class="field-section">Reproduction & evidence</div>'+field('steps','Steps to reproduce',v('steps'),'textarea',null,true)+field('expected','Expected result',v('expected'),'textarea')+field('actual','Actual result',v('actual'),'textarea')+field('environment','Environment / browser / version',v('environment'),'text',null,true)+'<div class="field-section">Mitigation & verification</div>'+field('mitigation','Mitigation approach',v('mitigation'),'textarea',null,true)+field('implementationStatus','Implementation status',v('implementationStatus')||'not_started','',['not_started','coding','pull_request','merged','deployed'])+`<div><label>Test status · derived from execution evidence</label>${badge(v('testStatus')||'not_run')}<p class="muted">Changes automatically when linked tests are run or evidence changes.</p></div>`+field('notes','Mitigation notes',v('notes'),'textarea',null,true)+`<label class="wide"><input name="notify" type="checkbox" ${item.notify!==false?'checked':''}>Notify relevant team members about updates</label>`;
  if(kind==='iterations')fields=field('name','Iteration name',v('name'),'text',null,true,true)+field('startDate','Start date',v('startDate'),'date',null,false,true)+field('endDate','End date',v('endDate'),'date',null,false,true)+field('goal','Iteration goal',v('goal'),'textarea',null,true);
  if(kind==='cases')fields=field('title','Test case title',v('title'),'text',null,true,true)+field('kind','Test kind',v('kind')||'functional','',['functional','regression','integration','smoke','acceptance'])+field('issueId','Linked issue',v('issueId'),'',issueOpts)+field('preconditions','Preconditions',v('preconditions'),'textarea',null,true)+field('steps','Execution steps',v('steps'),'textarea',null,true)+field('expected','Expected result',v('expected'),'textarea',null,true);
  if(kind==='runs')fields=field('caseId','Test case',v('caseId'),'',data.cases.map(c=>[c.id,c.title]),true,true)+field('issueId','Linked issue',v('issueId'),'',issueOpts)+field('iterationId','Iteration',v('iterationId'),'',iterOpts)+field('result','Result',v('result')||'not_run','',['not_run','passed','failed','blocked'])+field('environment','Environment',v('environment'),'text',null,false,true)+field('build','Build / commit / version',v('build'),'text',null,true,true)+field('actual','Actual result / evidence',v('actual'),'textarea',null,true)+field('notes','Notes',v('notes'),'textarea',null,true);
  const canEdit=kind==='iterations'?isEditor():isContributor();
  openDialog(`${item.id?'Edit':'New'} ${human({issues:'issue',iterations:'iteration',cases:'test case',runs:'test run'}[kind])}`,`<form id="entity-form">${kind==='issues'?evidencePanel(item):''}<fieldset ${canEdit?'':'disabled'} class="form-grid">${fields}</fieldset><div class="form-error" role="alert"></div><div class="dialog-foot">${item.id&&isEditor()?'<button type="button" class="btn danger" data-action="archive-record">Archive</button>':''}<button type="button" class="btn" data-action="close-modal">Cancel</button>${canEdit?'<button class="btn primary" type="submit">Save changes</button>':''}</div></form>${kind==='issues'&&item.id?issueQuality(item)+issueDelivery(item):''}`);
  if(kind==='issues'&&item.id)loadEvidence(item.id).catch(err=>{const target=$('#evidence-error');if(target)target.textContent=err.message;});
}
async function loadEvidence(issueId){const container=$('#evidence-list');for(const a of data.attachments.filter(a=>a.issueId===issueId)){let blob;if(n8nMode){const {file}=await api(base()+`/attachments/${a.id}`);blob=new Blob([Uint8Array.from(atob(file.data.replace(/\s/g,'')),c=>c.charCodeAt(0))],{type:file.type});}else{const r=await fetch(url(base()+`/attachments/${a.id}`),{headers:{Authorization:`Bearer ${token}`}});if(!r.ok)continue;blob=await r.blob();}const objectUrl=URL.createObjectURL(blob);const figure=document.createElement('figure');figure.innerHTML=`<a href="${objectUrl}" target="_blank" rel="noopener"><img src="${objectUrl}" alt="${esc(a.name)}"></a><figcaption>${esc(a.name)}</figcaption>${isEditor()||a.createdBy===me.id?`<button type="button" class="btn small" data-action="remove-evidence" data-id="${a.id}">Remove</button>`:''}`;container.append(figure);$('#modal').addEventListener('close',()=>URL.revokeObjectURL(objectUrl),{once:true});}}
function projectForm(edit=false){const p=edit?data.project:{};modalRecord={kind:'projects',item:p};openDialog(edit?'Edit project':'Create a project',`<form id="project-form"><div class="form-grid">${field('name','Project name',p.name,'text',null,true,true)}${field('description','Description',p.description,'textarea',null,true)}${field('repository','GitHub repository (owner/repository)',p.repository,'text',null,true)}</div><div class="form-error" role="alert"></div><div class="dialog-foot">${edit?'<button type="button" class="btn danger" data-action="archive-project">Archive project</button>':''}<button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">${edit?'Save project':'Create project'}</button></div></form>`);}
function showChat(){openDialog('Pandora assistant',`<p class="muted">Ask for triage suggestions, test ideas or a summary. Repository changes will require approval.</p><div class="chat-log" id="chat-log">${chatMessages.map(m=>`<div class="chat-msg ${m.role}">${esc(m.text)}</div>`).join('')||'<div class="chat-msg">What would you like to investigate in this project?</div>'}</div><form class="chat-form" id="chat-form"><input name="message" aria-label="Message to assistant" placeholder="Help me investigate an issue…" required maxlength="4000"><button class="btn primary">Send →</button></form><div class="form-error" role="alert"></div>`);}
document.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b)return;
  try{
    if(b.dataset.view){view=b.dataset.view;render();return;}
    const action=b.dataset.action;if(!action)return;
    if(['edit','run-case','refresh-issue','remove-evidence'].includes(action)&&$('#modal').open&&modalRecord?.kind==='issues'&&(modalRecord.dirty||modalRecord.pendingFiles?.length)){toast('Save your issue changes and pending screenshots first.');return;}
    if(action==='close-modal'){$('#modal').close();return;}
    if(action==='pipeline-toggle'){await api(base()+'/pipelines',{method:'PUT',body:{enabled:!data.project.pipelineConnection?.enabled,revision:data.project.pipelineConnection?.revision||0}});await refresh();return;}
    if(action==='refresh-pipelines'){await refresh();return;}
    if(action==='reset-login'){challengeId='';renderLogin();return;}
    if(action==='logout'){await api('/auth/logout',{method:'POST'});token=null;me=null;sessionStorage.removeItem('pandora-session');renderLogin();return;}
    if(action==='new-project'){projectForm();return;}
    if(!data)return;
    if(action==='new'){if(b.dataset.kind==='runs'&&!data.cases.length){toast('Create a test case first.');return;}entityForm(b.dataset.kind);}
    if(action==='edit')entityForm(b.dataset.kind,data[b.dataset.kind].find(x=>x.id===b.dataset.id));
    if(action==='run-case'){const c=data.cases.find(c=>c.id===b.dataset.id);entityForm('runs',{}, {caseId:c.id,issueId:c.issueId});}
    if(action==='edit-project')projectForm(true);
    if(action==='chat')showChat();
    if(action==='heatmap'){filter.priority=b.dataset.priority;view='backlog';render();}
    if(action==='clear-filters'){filter={q:'',priority:'',status:'',type:'',owner:'',iteration:'',sort:'newest'};render();}
    if(action==='notifications'){openDialog('Your project inbox',data.notifications.length?[...data.notifications].reverse().map(n=>`<article class="activity"><strong>${esc(n.title)}</strong><small>${esc(human(n.event))} · ${formatDate(n.at)}</small></article>`).join(''):empty('You’re all caught up','Relevant team updates will appear here.'));await api(base()+'/notifications/read',{method:'POST'});await refresh();}
    if(action==='archive-record'){if(!confirm('Archive this record? Its history will remain available in Activity.'))return;await api(base()+`/${modalRecord.kind}/${modalRecord.item.id}`,{method:'DELETE'});$('#modal').close();await refresh();toast('Record archived');}
    if(action==='archive-project'){if(!confirm('Archive this project and hide it from all members? Its data will be retained.'))return;await api(base(),{method:'DELETE'});$('#modal').close();projectId='';await loadProjects();toast('Project archived');}
    if(action==='remove-member'){if(!confirm('Remove this member’s access to the project?'))return;await api(base()+`/members/${b.dataset.id}`,{method:'DELETE'});await loadProjects();toast('Member removed');}
    if(action==='remove-pending'){modalRecord.pendingFiles.splice(Number(b.dataset.index),1);renderPendingEvidence();}
    if(action==='refresh-issue'){if(modalRecord.pendingFiles?.length){toast('Save your pending screenshots first.');return;}const id=modalRecord.item.id;await refresh();$('#modal').close();entityForm('issues',data.issues.find(i=>i.id===id));}
    if(action==='prepare-delivery'){if(modalRecord.dirty||modalRecord.pendingFiles.length)throw Error('Save issue changes and screenshots before preparing a handoff');const issue=modalRecord.item;modalRecord.deliveryRequestId??=crypto.randomUUID();await api(base()+'/issues/'+issue.id+'/deliveries',{method:'POST',body:{repository:$('#delivery-repository').value,issueVersion:issue.version,requestId:modalRecord.deliveryRequestId}});await refresh();$('#modal').close();entityForm('issues',data.issues.find(i=>i.id===issue.id));toast('Handoff prepared. No agent run has started.');}
    if(action==='queue-delivery'){if(modalRecord.dirty||modalRecord.pendingFiles.length)throw Error('Save issue changes before requesting a fix');const j=data.deliveries.find(j=>j.id===b.dataset.id),issue=modalRecord.item;await api(base()+'/deliveries/'+j.id+'/queue',{method:'POST',body:{version:j.version}});await refresh();$('#modal').close();entityForm('issues',data.issues.find(i=>i.id===issue.id));toast('Fix request queued for a connected Codex worker');}
    if(action==='link-delivery-pr'){if(modalRecord.dirty||modalRecord.pendingFiles.length)throw Error('Save issue changes before linking a PR');const job=data.deliveries.find(j=>j.id===b.dataset.id);openDialog('Link a fix pull request',`<form id="delivery-pr-form" data-id="${job.id}" data-version="${job.version}"><p>Repository: ${esc(job.repository)}</p><p>Add this opaque marker on its own line in the PR description:</p><pre>${esc('Pandora-Delivery: '+job.id)}</pre><p>Keep private issue text and screenshots out of public PRs. GitHub metadata will be checked during the next poll.</p><label>Pull request number<input name="number" type="number" min="1" step="1" required></label><div class="form-error" role="alert"></div><button type="submit" class="btn primary">Request link verification</button></form>`);}
    if(action==='delivery-targets'){if(modalRecord.dirty||modalRecord.pendingFiles.length)throw Error('Save issue changes before choosing deployment targets');const j=data.deliveries.find(j=>j.id===b.dataset.id);openDialog('Deployment targets',`<form id="delivery-targets-form" data-id="${j.id}" data-version="${j.version}"><p>Select every environment/component that must deliver this fix. Revision checks are separate from functional tests.</p>${[['production_frontend','Production frontend'],['production_backend','Production backend'],['sandbox_frontend','Sandbox frontend']].map(([id,label])=>`<label><input type="checkbox" name="${id}" ${j.deploymentPlan?.targets.includes(id)?'checked':''}>${label}</label>`).join('')}<div class="form-error" role="alert"></div><button class="btn primary" type="submit">Save targets</button></form>`);}
    if(action==='download-delivery'){const context=await api(base()+'/deliveries/'+b.dataset.id+'/context');const u=URL.createObjectURL(new Blob([JSON.stringify(context,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='pandora-handoff-'+b.dataset.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
    if(action==='cancel-delivery'){const job=data.deliveries.find(j=>j.id===b.dataset.id),issue=modalRecord.item;await api(base()+'/deliveries/'+job.id+'/cancel',{method:'POST',body:{version:job.version}});await refresh();$('#modal').close();entityForm('issues',data.issues.find(i=>i.id===issue.id));}
    if(action==='generate-tests'){await api(base()+`/issues/${modalRecord.item.id}/generate-tests`,{method:'POST'});toast('Test generation queued. Refresh this issue shortly.');}
    if(action==='all-tests'){aggregateTests=await api('/tests');render();}
    if(action==='project-tests'){aggregateTests=null;if(b.dataset.project){projectId=b.dataset.project;await refresh();}else render();}
    if(action==='configure-cadence'){cadenceForm();}
    if(action==='accept-iteration'){const issue=data.issues.find(i=>i.id===b.dataset.id);const fields=['title','description','type','priority','severity','status','ownerId','iterationId','steps','expected','actual','environment','mitigation','notes','implementationStatus','dueDate','estimate','notify'];const body=Object.fromEntries(fields.map(k=>[k,issue[k]]));await api(base()+`/issues/${issue.id}`,{method:'PUT',body:{...body,iterationId:issue.iterationSuggestion.id,version:issue.version}});await refresh();toast('Iteration assignment accepted');}
    if(action==='remove-evidence'){await api(base()+`/attachments/${b.dataset.id}`,{method:'DELETE'});const issueId=modalRecord.item.id;await refresh();$('#modal').close();entityForm('issues',data.issues.find(i=>i.id===issueId));}
  }catch(err){toast(err.message);}
});
document.addEventListener('submit',async e=>{
  e.preventDefault();const form=e.target;const submit=form.querySelector('button[type=submit]')||form.querySelector('button:last-of-type');if(submit)submit.disabled=true;
  const values=Object.fromEntries(new FormData(form));
  try{
    if(form.id==='login-form'){
      mailEmail=values.email;
      if(!challengeId){const r=await api('/auth/request',{method:'POST',body:{email:values.email}});challengeId=r.challengeId;renderLogin();$('#login-status').textContent=r.message;}
      else{const r=await api('/auth/verify',{method:'POST',body:{challengeId,code:values.code}});token=r.token;me=r.user;sessionStorage.setItem('pandora-session',token);challengeId='';await loadProjects();}
    }
    if(form.id==='project-form'){const p=modalRecord.item;const r=await api(p.id?`/projects/${p.id}`:'/projects',{method:p.id?'PUT':'POST',body:{...values,mergePolicy:p.mergePolicy||'human',...(p.id?{version:p.version}:{})}});projectId=r.id;$('#modal').close();await loadProjects();toast('Project saved');}
    if(form.id==='entity-form'){
      const {kind,item}=modalRecord;if(kind==='issues'){values.estimate=Number(values.estimate);values.notify=form.elements.notify.checked;}
      const saved=await api(base()+`/${kind}${item.id?'/'+item.id:''}`,{method:item.id?'PUT':'POST',body:{...values,...(item.id?{version:item.version}:{})}});modalRecord.item=saved;modalRecord.dirty=false;
      if(kind==='issues'){while(modalRecord.pendingFiles.length){const file=modalRecord.pendingFiles[0];await uploadEvidence(saved.id,file);modalRecord.pendingFiles.shift();renderPendingEvidence();}}
      $('#modal').close();await refresh();toast(kind==='issues'?'Issue saved. Test drafts will update in the background.':'Saved successfully');
    }
    if(form.id==='delivery-targets-form'){const targets=['production_frontend','production_backend','sandbox_frontend'].filter(id=>form.elements[id].checked);if(!targets.length)throw Error('Select at least one deployment target');await api(base()+'/deliveries/'+form.dataset.id+'/targets',{method:'PUT',body:{version:Number(form.dataset.version),targets}});$('#modal').close();await refresh();toast('Deployment targets saved');}
    if(form.id==='delivery-pr-form'){await api(base()+'/deliveries/'+form.dataset.id+'/pull',{method:'PUT',body:{number:Number(values.number),version:Number(form.dataset.version)}});$('#modal').close();await refresh();toast('PR link requested. Reopen the issue after the next pipeline poll.');}
    if(form.id==='cadence-form'){await api(base()+'/cadence',{method:'PUT',body:{enabled:form.elements.enabled.checked,startDate:values.startDate,lengthDays:Number(values.lengthDays),lookahead:Number(values.lookahead)}});$('#modal').close();await refresh();toast('Iteration cadence saved');}
    if(form.id==='member-form'){await api(base()+'/members',{method:'POST',body:values});await loadProjects();toast('Membership saved');}
    if(form.id==='chat-form'){chatMessages.push({role:'user',text:values.message});$('#chat-log').insertAdjacentHTML('beforeend',`<div class="chat-msg user">${esc(values.message)}</div>`);form.reset();const r=await api(base()+'/chat',{method:'POST',body:values});chatMessages.push({role:'assistant',text:r.reply});$('#chat-log').insertAdjacentHTML('beforeend',`<div class="chat-msg">${esc(r.reply)}</div>`);}
  }catch(err){const target=form.querySelector('.form-error')||$('#login-status')||$('#modal .form-error');if(target)target.textContent=err.message;else toast(err.message);}finally{if(submit)submit.disabled=false;}
});
document.addEventListener('change',async e=>{try{
  if(e.target.id==='project-picker'){projectId=e.target.value;chatMessages=[];await refresh();}
  if(e.target.dataset.filter){filter[e.target.dataset.filter]=e.target.value;render();}
  if(e.target.id==='mute-notifications'){await api(base()+'/preferences',{method:'PUT',body:{muted:e.target.checked}});toast('Notification preferences saved');await refresh();}
  if(e.target.id==='screenshot'){queueEvidence(e.target.files);e.target.value='';}
}catch(err){toast(err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='search'){filter.q=e.target.value;$('#issue-results').innerHTML=issueTable(filteredIssues())+`<div class="table-count">${filteredIssues().length} of ${data.issues.length} issues</div>`;}});
async function init(){if(token){try{me=await api('/me');await loadProjects();return;}catch(err){toast(err.message);}}renderLogin();}
init();



let pendingPreviewUrls=[];
function evidencePanel(item){return `<section class="evidence issue-evidence"><div class="panel-title"><div><h3>Screenshots & evidence</h3><p>Attach the screen state that demonstrates the defect. Images inform the generated test drafts.</p></div><span class="badge">${data.attachments.filter(a=>a.issueId===item.id).length} saved</span></div><div id="evidence-list" class="evidence-list"></div><div id="pending-evidence" class="evidence-list"></div>${isContributor()?'<label id="evidence-drop" class="evidence-drop">Drop screenshots here, paste an image, or choose files<input id="screenshot" type="file" multiple accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG or WebP · 5 MB each · up to 10 per issue · uploaded when you save</small></label>':''}<p id="evidence-error" class="form-error" role="alert"></p></section>`;}
function queueEvidence(files){if(modalRecord?.kind!=='issues'||!isContributor())return;const saved=data.attachments.filter(a=>a.issueId===modalRecord.item.id).length;for(const file of files){if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Choose PNG, JPEG or WebP screenshots.');continue;}if(file.size>5*1024*1024){toast(`${file.name}: maximum size is 5 MB`);continue;}if(saved+modalRecord.pendingFiles.length>=10){toast('Maximum 10 screenshots per issue');break;}if(!modalRecord.pendingFiles.some(f=>f.name===file.name&&f.size===file.size&&f.lastModified===file.lastModified))modalRecord.pendingFiles.push(file);}renderPendingEvidence();}
function renderPendingEvidence(){for(const u of pendingPreviewUrls)URL.revokeObjectURL(u);pendingPreviewUrls=[];const target=$('#pending-evidence');if(!target)return;target.innerHTML=(modalRecord.pendingFiles||[]).map((f,i)=>{const url=URL.createObjectURL(f);pendingPreviewUrls.push(url);return `<figure><img src="${url}" alt="Preview of ${esc(f.name)}"><figcaption>${esc(f.name)} · pending</figcaption><button type="button" class="btn small" data-action="remove-pending" data-index="${i}">Remove</button></figure>`;}).join('');}
async function uploadEvidence(issueId,file){const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await api(base()+`/issues/${issueId}/attachments`,{method:'POST',body:{name:file.name,type:file.type,data:encoded}});}
function issueQuality(issue){const cases=data.cases.filter(c=>c.issueId===issue.id),runs=data.runs.filter(r=>r.issueId===issue.id),g=issue.testGeneration;return `<section class="issue-quality"><div class="panel-title"><div><h3>Tests & verification</h3><p>Generated from this issue and its screenshots. Manual edits and executed test versions are preserved.</p></div>${badge(issue.testStatus)}</div><div class="notice">${g?`Generation: ${esc(human(g.state))}. ${esc(g.error||g.notes||'Drafts are not execution results; review them before testing.')}`:'This issue predates automatic generation. Generate its first test draft below.'}</div><div class="actions"><button class="btn small" data-action="refresh-issue">Refresh issue</button>${isContributor()?'<button class="btn small" data-action="generate-tests">Regenerate drafts</button>':''}</div>${cases.length?`<div class="table-wrap"><table><thead><tr><th>Test case</th><th>Review</th><th>Actions</th></tr></thead><tbody>${cases.map(c=>`<tr><td>${esc(c.title)}<br><small>${esc(c.expected)}${c.sourceRevision&&c.sourceRevision!==issue.evidenceRevision?' · Created from earlier evidence':''}</small></td><td>${badge(c.source==='ai'&&!c.manualEdited?'draft':'reviewed')}</td><td><button class="btn small" data-action="edit" data-kind="cases" data-id="${c.id}">Review / edit</button>${isContributor()?`<button class="btn small" data-action="run-case" data-id="${c.id}">Record result</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Test drafts are being prepared','You can also maintain cases manually in Test management.')}<h4>Execution evidence</h4>${runs.length?runs.slice().reverse().map(r=>`<div class="activity"><strong>${esc(r.caseSnapshot?.title)}</strong> ${badge(r.result)}<small>${esc(r.environment)} · ${esc(r.build)} · ${formatDate(r.createdAt)}</small></div>`).join(''):empty('No execution results yet')}<p class="muted">Passing status requires current evidence and current test versions. AI generation never marks a test as passed.</p></section>`;}
function cadenceForm(){const c=data.project.cadence||{enabled:true,startDate:new Date().toISOString().slice(0,10),lengthDays:14,lookahead:3};openDialog('Iteration cadence',`<form id="cadence-form"><p>Create current and upcoming iterations automatically. Existing edited or archived iterations are preserved. Suggested assignments require your review.</p><label><input type="checkbox" name="enabled" ${c.enabled?'checked':''}>Automatically maintain iterations</label><div class="form-grid">${field('startDate','Cadence anchor date',c.startDate,'date',null,false,true)}${field('lengthDays','Days per iteration (7–42)',c.lengthDays,'number',null,false,true)}${field('lookahead','Iterations to keep ahead (1–6)',c.lookahead,'number',null,false,true)}</div><div class="form-error" role="alert"></div><div class="dialog-foot"><button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn primary">Save cadence</button></div></form>`);}
function iterationSuggestions(){const suggestions=data.issues.filter(i=>i.iterationSuggestion);return `<section class="panel"><div class="panel-title"><div><h2>Suggested assignments</h2><p>${data.project.cadence?.enabled?`${data.project.cadence.lengthDays}-day cadence · ${data.project.cadence.lookahead} upcoming iterations`:'Configure a cadence to create iterations automatically.'}</p></div></div>${suggestions.length?`<div class="table-wrap"><table><thead><tr><th>Issue</th><th>Suggested iteration</th><th>Reason</th><th></th></tr></thead><tbody>${suggestions.map(i=>`<tr><td>${esc(i.title)}</td><td>${esc(data.iterations.find(it=>it.id===i.iterationSuggestion.id)?.name)}</td><td>${esc(i.iterationSuggestion.reason)}</td><td>${isEditor()?`<button class="btn small" data-action="accept-iteration" data-id="${i.id}">Accept assignment</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('No assignments awaiting review')}</section><br>`;}
document.addEventListener('dragover',e=>{if(e.target.closest('#evidence-drop')){e.preventDefault();e.dataTransfer.dropEffect='copy';}});
document.addEventListener('drop',e=>{if(e.target.closest('#evidence-drop')){e.preventDefault();queueEvidence(e.dataTransfer.files);}});
document.addEventListener('paste',e=>{if($('#modal').open&&modalRecord?.kind==='issues'&&e.clipboardData.files.length){e.preventDefault();queueEvidence(e.clipboardData.files);}});
$('#modal').addEventListener('close',()=>{for(const u of pendingPreviewUrls)URL.revokeObjectURL(u);pendingPreviewUrls=[];});

function aggregateTestView(){return heading('Test coverage across your projects.','Only projects you belong to are included. Open a project to review or edit its tests.','<button class="btn" data-action="project-tests">Current project</button>')+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Project</th><th>Issue</th><th>Test case</th><th>Issue verification</th><th></th></tr></thead><tbody>${aggregateTests.cases.map(c=>`<tr><td>${esc(aggregateTests.projects.find(p=>p.id===c.projectId)?.name)}</td><td>${esc(c.issueTitle||'Unlinked')}</td><td>${esc(c.title)} ${c.source==='ai'&&!c.manualEdited?badge('draft'):''}</td><td>${badge(c.issueTestStatus)}</td><td><button class="btn small" data-action="project-tests" data-project="${c.projectId}">Open project</button></td></tr>`).join('')}</tbody></table></div>${aggregateTests.cases.length?'':empty('No test cases yet')}</section>`;}

document.addEventListener('input',e=>{if(e.target.closest('#entity-form')&&modalRecord?.kind==='issues')modalRecord.dirty=true;});
function pipelines(){
 const c=data.project.pipelineConnection,e=data.project.pipelineEvidence;
 const link=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
 const time=v=>v?new Date(v).toLocaleString():'Not recorded';
 return heading('Repository evidence, in context.','Read-only GitHub pipeline observations. Functional verification remains a separate step.',`<button class="btn" data-action="refresh-pipelines">Refresh view</button>`)+`<section class="panel"><div class="panel-title"><h2>Intellectual Twin connection</h2>${badge(c?.enabled?'enabled':'disabled')}</div><p>florianliepe/meids-app · main · production frontend, production backend and Pages sandbox.<br>florianliepe/meids-agent-configs · main · configuration source only; no CI configured.</p>${data.role==='owner'?`<button class="btn" data-action="pipeline-toggle">${c?.enabled?'Disconnect polling':'Connect Intellectual Twin repositories'}</button>`:''}<p><small>Polls every five minutes while enabled. Displays up to three recent runs per workflow. Last observation: ${esc(time(e?.observedAt))}.</small></p>${e&&Date.now()-Date.parse(e.observedAt)>900000?'<div class="notice">Observations are older than 15 minutes. Treat this view as stale until polling succeeds.</div>':''}${!c?.enabled&&e?'<div class="notice">Polling is disabled. The last collected evidence is retained.</div>':''}<div class="notice">Workflow success is not proof that every functional test passed. Advisory steps may allow a workflow to succeed. CI observations do not close issues or populate DORA deployment metrics.</div>${(e?.errors||[]).map(x=>`<p role="status">${esc(x)}</p>`).join('')}</section><br>${!e?empty('Awaiting the first observation','Connect the repositories and return after the next five-minute poll.'): `<section class="panel"><h2>Source revisions</h2>${e.sources.map(s=>`<p>${esc(s.repository)} · ${esc(s.role)}<br>${s.commit?link('https://github.com/'+s.repository+'/commit/'+s.commit,s.commit.slice(0,12)):'Source unavailable'}</p>`).join('')}</section><br><section class="panel"><h2>Workflow runs and validation steps</h2>${e.runs.length?e.runs.map(r=>`<details class="pipeline-run"><summary>${esc(r.name)} · ${esc(r.environment)} · ${esc(r.commit.slice(0,8))} · ${esc(r.status==='completed'?r.conclusion:r.status)}${r.stale?' · stale':''}</summary><p>${link(r.url,'Open run '+r.id)} · attempt ${r.attempt} · ${esc(r.event)} · ${esc(time(r.updatedAt))}</p>${r.jobs.length?r.jobs.map(j=>`<h3>${esc(j.name)} ${badge(j.status==='completed'?j.conclusion:j.status)}</h3><div class="table-wrap"><table><thead><tr><th>Step</th><th>Result</th></tr></thead><tbody>${j.steps.map(s=>`<tr><td>${esc(s.name)}</td><td>${badge(s.status==='completed'?s.conclusion:s.status)}</td></tr>`).join('')}</tbody></table></div>`).join(''):'<p>Job details unavailable or not yet started.</p>'}${r.jobsTruncated?'<p>Additional jobs are available on GitHub.</p>':''}</details>`).join(''):empty('No matching workflow runs')}</section><br><section class="panel"><h2>Historical UAT evidence</h2><div class="notice">These are versioned repository records, not tests executed by this poll. The source commit identifies the file version; it does not prove the tested application revision. Failures may predate subsequent fixes.</div>${e.uat?`<p>${link(e.uat.url,'View original UAT evidence')} · source ${esc(e.uat.sourceCommit.slice(0,12))}${e.uat.stale?' · stale':''}<br>Reported execution timestamp: ${esc(e.uat.reportedAt||'Not recorded')} · ${e.uat.totalCases} recorded cases</p><div class="table-wrap"><table><thead><tr><th>Case</th><th>Recorded status</th><th>Findings</th></tr></thead><tbody>${e.uat.cases.map(c=>`<tr><td>${esc(c.id)}</td><td>${badge(c.status)}</td><td>${esc(c.findings)}</td></tr>`).join('')}</tbody></table></div>${e.uat.totalCases>e.uat.cases.length?'<p>Showing the first 40 cases. Open the original for all evidence.</p>':''}`:empty('No supported UAT evidence available')}</section>`}`;
}
function issueDelivery(issue){const jobs=(data.deliveries||[]).filter(j=>j.issueId===issue.id);return `<section class="issue-quality"><h3>Fix handoff & delivery</h3><p>Capture the saved report, screenshots and test versions against a verified repository revision.</p><div class="notice">Preparing a handoff does not start an agent, create a PR, run tests or prove delivery. PR metadata is checked through GitHub. A connected Codex worker must claim queued work; development PR merges remain human-controlled. Deployment verification is being integrated.</div>${isEditor()?`<label>Development repository<select id="delivery-repository"><option>florianliepe/meids-app</option><option>florianliepe/meids-agent-configs</option></select></label><button type="button" class="btn small" data-action="prepare-delivery" ${data.project.pipelineConnection?.enabled?'':'disabled'}>Prepare fix handoff</button>${!data.project.pipelineConnection?.enabled?'<p>Connect repositories in Repositories & CI first.</p>':''}`:''}${jobs.length?jobs.slice().reverse().map(j=>`<article class="activity"><strong>${esc(j.repository)} · ${esc(j.baseSha.slice(0,12))}</strong>${badge(j.state)}<small>${formatDate(j.createdAt)} · report revision ${j.evidenceRevision} · ${j.evidenceCurrent?'Evidence unchanged':'Evidence changed; prepare a new handoff'}</small><div class="actions">${j.state!=='cancelled'&&j.evidenceCurrent?`<button type="button" class="btn small" data-action="download-delivery" data-id="${j.id}">Download private handoff</button>`:''}${j.state!=='cancelled'&&j.evidenceCurrent&&isEditor()?`<button type="button" class="btn small" data-action="link-delivery-pr" data-id="${j.id}">Link fix PR</button>`:''}${['prepared','needs_input','failed'].includes(j.state)&&j.evidenceCurrent&&isEditor()?`<button type="button" class="btn small" data-action="queue-delivery" data-id="${j.id}">Request fix & tests</button>`:''}${['prepared','queued','running','needs_input','failed'].includes(j.state)&&isEditor()?`<button type="button" class="btn small" data-action="cancel-delivery" data-id="${j.id}">Cancel handoff</button>`:''}</div>${deliveryPullStatus(j)}${deliveryTargetStatus(j)}${deliveryTestStatus(j)}</article>`).join(''):empty('No fix handoff yet')}</section>`;}
function deliveryPullStatus(job){const p=job.pullObservation;if(!job.pullRequest)return '';if(!p)return '<p>PR #'+job.pullRequest.number+' · awaiting GitHub verification.</p>';return `<p>PR #${p.number||job.pullRequest.number} · ${esc(p.stale?'stale observation':p.correlationVerified?'repository and handoff correlation verified':'correlation not verified')}<br>${esc(p.error||'')}${p.headSha?`<br>Candidate: ${esc(p.headSha.slice(0,12))}`:''}${p.merged?`<br>GitHub reports merged · ${esc(p.mergeSha?.slice(0,12)||'merge revision unavailable')}`:''}</p><p class="muted">PR identity and merge status do not prove tests passed or the fix was deployed.</p>`;}
function deliveryTestStatus(job){const reports=job.testReports||[];return `${job.workerSummary?`<p>${esc(job.workerSummary)}</p>`:''}${reports.length?`<h4>Worker test evidence</h4><p class="muted">Reports from the authenticated Codex worker. Candidate results are separate from post-deployment verification.</p>${reports.slice().reverse().map(r=>`<p>${badge(r.phase)} ${esc(r.kind)} · ${esc(r.commit.slice(0,12))} · exit ${r.exitCode}<br><small>${r.tests.filter(t=>t.result==='passed').length}/${r.tests.length} passed · ${esc(r.environment)}</small></p>`).join('')}`:''}`;}

function deliveryTargetStatus(j){return `<h4>Deployment targets</h4>${j.deploymentPlan?j.deploymentPlan.targets.map(id=>{const o=j.deploymentObservations?.[id];return `<p>${esc(id.replaceAll('_',' '))}: ${o?.verified?'served revision matched':'awaiting revision evidence'}${o?`<br><small>${esc(o.error||o.commit)} · ${formatDate(o.observedAt)}</small>`:''}</p>`;}).join(''):'<p>No deployment targets selected.</p>'}${isEditor()&&j.repository==='florianliepe/meids-app'&&j.evidenceCurrent&&['prepared','needs_input','failed','awaiting_review'].includes(j.state)?`<button type="button" class="btn small" data-action="delivery-targets" data-id="${j.id}">Choose deployment targets</button>`:''}<p class="muted">A matched revision does not prove functional acceptance.</p>`;}
